queries.userProgressSubmissionList:
query userProgressSubmissionList($offset: Int!, $limit: Int!, $questionSlug: String!) {
  userProgressSubmissionList(
    offset: $offset
    limit: $limit
    questionSlug: $questionSlug
  ) {
    submissions {
      id
      status
      langName
      runtime
      timestamp
      memory
    }
    totalNum
  }
}

queries.userProgressQuestionList:
    query userProgressQuestionList($filters: UserProgressQuestionListInput) {
  userProgressQuestionList(filters: $filters) {
    totalNum
    questions {
      translatedTitle
      frontendId
      title
      titleSlug
      difficulty
      lastSubmittedAt
      numSubmitted
      questionStatus
      lastResult
      topicTags {
        name
        nameTranslated
        slug
      }
    }
  }
}
